    case 20: /* CHANNEL */
    case 21: /* CLASS_ORIGIN */
    case 22: /* COALESCE */
    case 23: /* CODE */
    case 24: /* COLLATE */
    case 25: /* COLUMN */
    case 26: /* COLUMN_NAME */
    case 27: /* COMMENT */
    case 28: /* COMPLETION */
    case 29: /* COMPRESSION */
    case 30: /* CONSISTENT */
    case 31: /* CONSTRAINT */
    case 32: /* CONSTRAINT_CATALOG */
    case 33: /* CONSTRAINT_NAME */
    case 34: /* CONSTRAINT_SCHEMA */
    case 35: /* CONTAINS */
    case 36: /* CONTEXT */
    case 37: /* CONVERT */
    case 38: /* CPU */
    case 39: /* CURRENT */
    case 40: /* CURSOR_NAME */
    case 41: /* CURRENT_USER */
    case 42: /* DATAFILE */
    case 43: /* DECIMAL */
    case 44: /* DEFINITION */
    case 45: /* DELAY_KEY_WRITE */
    case 46: /* DESCRIPTION */
    case 47: /* DETERMINISTIC */
    case 48: /* DIRECTORY */
    case 49: /* DISCARD */
    case 50: /* DUMPFILE */
    case 51: /* DUPLICATE */
    case 52: /* EACH */
    case 53: /* ENABLE */
    case 54: /* ENCRYPTION */
    case 55: /* ENFORCED */
    case 56: /* ENGINE_ATTRIBUTE */
    case 57: /* EVERY */
    case 58: /* EXCHANGE */
    case 59: /* EXCEPT */
    case 60: /* EXISTS */
    case 61: /* EXPORT */
    case 62: /* EXTENT_SIZE */
    case 63: /* FAST */
    case 64: /* FAULTS */
    case 65: /* FILE_BLOCK_SIZE */
    case 66: /* FILTER */
    case 67: /* FOLLOWS */
    case 68: /* FORCE */
    case 69: /* FOREIGN */
    case 70: /* FOUND */
    case 71: /* GENERAL */
